  '[{"id":"tc1","validation_type":"matching","expected_value":"Recompute against the source","description_en":"Hallucination","description_id":"Halusinasi","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Anonymize or use an approved tool","description_en":"Privacy","description_id":"Privasi","points":25},{"id":"tc3","validation_type":"matching","expected_value":"Ask the AI to show its working","description_en":"Over-trust","description_id":"Terlalu percaya","points":25},{"id":"tc4","validation_type":"matching","expected_value":"Give context, task, and constraints","description_en":"Vague prompt","description_id":"Prompt samar","points":25}]',
