  '{"pairs":[{"left":"Draft a SQL query from a description","right":"AI drafts, analyst verifies"},{"left":"Decide which business question matters","right":"Analyst owns"},{"left":"Summarize patterns in plain words","right":"AI drafts, analyst verifies (interpret)"},{"left":"Sign off the final claim","right":"Analyst owns (accountable)"}]}','',
  '[{"id":"tc1","validation_type":"matching","expected_value":"AI drafts, analyst verifies","description_en":"Draft query","description_id":"Draf query","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Analyst owns","description_en":"Choose question","description_id":"Pilih pertanyaan","points":25},{"id":"tc3","validation_type":"matching","expected_value":"AI drafts, analyst verifies (interpret)","description_en":"Summarize","description_id":"Ringkas","points":25},{"id":"tc4","validation_type":"matching","expected_value":"Analyst owns (accountable)","description_en":"Sign off","description_id":"Tanda tangan","points":25}]',
